  'Seu microfone está bloqueado: ninguém está te ouvindo.': 'Dein Mikrofon ist blockiert: Niemand hört dich.',
  'Quem bloqueia é o Windows. Abra Configurações do Windows → Privacidade e segurança → Microfone e ligue o acesso para o navegador.': 'Windows blockiert es. Öffne Windows-Einstellungen → Datenschutz und Sicherheit → Mikrofon und erlaube den Zugriff für deinen Browser.',
  'Clique no ícone à esquerda do endereço do site, ative o Microfone, e o Syden liga sozinho.': 'Klick auf das Symbol links neben der Adresse der Seite, aktiviere das Mikrofon, und Syden schaltet es von selbst ein.',
