  'Administradores podem apagar mensagens de qualquer pessoa, gerenciar todos os canais, emojis e sons desta comunidade e remover membros. Só o dono dá e tira esse cargo.': 'Admins können die Nachrichten von allen löschen, alle Kanäle, Emojis und Sounds dieser Community verwalten und Mitglieder entfernen. Nur der Besitzer vergibt und nimmt diese Rolle.',
