  'Apaga a comunidade para todo mundo, com os canais, as mensagens, os emojis e os sons dela. Não dá para desfazer.': 'Löscht die Community für alle, mit ihren Kanälen, Nachrichten, Emojis und Sounds. Das lässt sich nicht rückgängig machen.',
  'Apagar {comunidade} para todos os {quantos} membros? Os canais, as mensagens, os emojis e os sons somem junto.': '{comunidade} für alle {quantos} Mitglieder löschen? Die Kanäle, die Nachrichten, die Emojis und die Sounds gehen mit.',
