  'Avisa das mensagens novas quando o Syden está minimizado, em segundo plano ou em outro canal.': 'Sagt dir Bescheid, wenn neue Nachrichten kommen und Syden minimiert, im Hintergrund oder auf einem anderen Kanal ist.',
