  'Colar imagem': 'Bild einfügen',
  'Como administrador, você pode remover membros que não são administradores.': 'Als Admin kannst du Mitglieder entfernen, die keine Admins sind.',
  'Como dono, você escolhe quem administra e pode remover qualquer pessoa.': 'Als Besitzer suchst du aus, wer verwaltet, und kannst jeden entfernen.',
  'Confete, fogos e corações que qualquer pessoa da sala pode mandar. Desligue se o seu computador engasgar durante a chamada — desligado, você não vê nem manda.': 'Konfetti, Feuerwerk und Herzen, die jeder im Raum schicken kann. Mach es aus, wenn dein Rechner im Gespräch ins Stocken gerät — aus siehst du sie nicht und schickst sie nicht.',
