  'Endereço guardado. O envio de e-mail ainda não está ligado neste servidor, então o link de confirmação ficou no registro do servidor.': 'Adresse gespeichert. Der E-Mail-Versand ist auf diesem Server noch nicht eingeschaltet, also ist der Bestätigungslink im Serverprotokoll gelandet.',
