  'Microfone': 'Mikrofon',
  'Modificador de voz': 'Stimmverzerrer',
  'Muda como os outros ouvem você na chamada. Vale na hora, dá para trocar durante a conversa — e acaba quando você sai da sala: na próxima você entra com a sua voz.': 'Ändert, wie die anderen dich im Gespräch hören. Es gilt sofort, du kannst mitten im Gespräch wechseln — und es endet, wenn du den Raum verlässt: beim nächsten Mal kommst du mit deiner Stimme rein.',
  'Nada faltando: o pacote está completo.': 'Nichts fehlt: das Paket ist vollständig.',
  'Não deu para salvar o selo.': 'Das Abzeichen ließ sich nicht speichern.',
