  'Nome alterado.': 'Name geändert.',
  'Notificações na área de trabalho': 'Benachrichtigungen auf dem Desktop',
  'O navegador bloqueou as notificações deste site. Libere no cadeado ao lado do endereço e recarregue a página.': 'Der Browser hat die Benachrichtigungen dieser Seite blockiert. Erlaub sie über das Schloss neben der Adresse und lade die Seite neu.',
  'O selo aparece aqui quando o primeiro marco cair. Até lá ele fica guardado — e chegar nele é justamente o que ele vai significar.': 'Das Abzeichen taucht hier auf, wenn der erste Meilenstein fällt. Bis dahin bleibt es liegen — und ihn zu erreichen ist genau das, wofür es stehen wird.',
