  'Quem tiver este código entra na comunidade: pela tela de cadastro, se ainda não tem conta, ou pelo botão de entrar, se já usa o Syden.': 'Wer diesen Code hat, kommt in die Community: über den Registrierungsbildschirm, wenn er noch kein Konto hat, oder über den Beitreten-Knopf, wenn er Syden schon benutzt.',
  'Reduz barulhos de fundo, como teclado, ventilador e trânsito.': 'Dämpft Hintergrundgeräusche wie Tastatur, Lüfter und Verkehr.',
