  'Selo da comunidade': 'Abzeichen der Community',
  'Senha alterada. Os outros aparelhos foram desconectados.': 'Passwort geändert. Die anderen Geräte wurden abgemeldet.',
  'Senha definida. Agora dá para entrar com nome e senha também.': 'Passwort festgelegt. Jetzt kommst du auch mit Name und Passwort rein.',
  'Serve para recuperar a senha e para avisar você se algo acontecer com o Syden. Sem e-mail, uma senha esquecida não tem volta.': 'Sie holt das Passwort zurück und warnt dich, wenn mit Syden etwas passiert. Ohne E-Mail hat ein vergessenes Passwort keinen Rückweg.',
