  'Teclas de atalho': 'Tastenkürzel',
  'Testar microfone': 'Mikrofon testen',
  'Tirar o selo': 'Das Abzeichen abnehmen',
  'Toca um som quando alguém entra ou sai da sua sala, quando alguém começa a compartilhar a tela e quando você silencia ou ensurdece.': 'Spielt einen Ton, wenn jemand deinen Raum betritt oder verlässt, wenn jemand den Bildschirm teilt und wenn du dich stumm schaltest oder taub stellst.',
  'Tocando…': 'Spielt…',
  'Todo mundo desta comunidade pode usar estes emojis escrevendo {exemplo} ou pelo botão de emoji do chat. Sem assinatura: está tudo liberado.': 'Alle in dieser Community können diese Emojis benutzen, indem sie {exemplo} schreiben oder den Emoji-Knopf im Chat nehmen. Kein Abo: alles ist freigeschaltet.',
  'Traz de volta os emojis que vêm com o Syden. O que vocês enviaram continua como está, e nada vira cópia repetida.': 'Holt die Emojis zurück, die mit Syden kommen. Was ihr hochgeladen habt, bleibt wie es ist, und nichts wird zum Doppel.',
  'Trocar áudio': 'Audio wechseln',
  'Trocar avatar': 'Avatar wechseln',
  'Usar este coelho': 'Diesen Hasen verwenden',
  'Trocar imagem': 'Bild wechseln',
  'Trocar o e-mail': 'Die E-Mail ändern',
  'Trocar senha': 'Passwort ändern',
  'Veja se o microfone está captando a sua voz.': 'Schau, ob das Mikrofon deine Stimme aufnimmt.',
  'Você ainda não tem nenhuma. Elas chegam como presente ou como recompensa — por exemplo, quando uma ideia sua entra no Syden.': 'Du hast noch keine. Sie kommen als Geschenk oder als Belohnung — zum Beispiel, wenn eine Idee von dir in Syden landet.',
  'Você entrou por um serviço de fora e ainda não tem senha nesta conta. Defina uma aqui: passa a valer como segundo jeito de entrar, e é o que permite desligar aquele serviço depois.': 'Du bist über einen fremden Dienst reingekommen und hast auf diesem Konto noch kein Passwort. Leg hier eins fest: es gilt dann als zweiter Weg hinein, und es ist das, was dir erlaubt, jenen Dienst später abzuhängen.',
  'Você perde o acesso aos canais desta comunidade. Para voltar, vai precisar de um convite novo.': 'Du verlierst den Zugang zu den Kanälen dieser Community. Um zurückzukommen, brauchst du eine neue Einladung.',
