  'Pessoas bloqueadas': 'Blockierte Leute',
  'Quem está aqui não vê as suas mensagens nem você as dele, não consegue abrir conversa privada com você e não pode te mandar pedido de amizade.': 'Wer hier steht, sieht deine Nachrichten nicht und du seine nicht, kann kein privates Gespräch mit dir öffnen und dir keine Freundschaftsanfrage schicken.',
