  'Nenhum pacote ainda. Monte o primeiro com imagens suas, ou publique os emojis que esta comunidade já tem.': 'Noch keine Pakete. Bau das erste mit deinen eigenen Bildern, oder veröffentliche die Emojis, die diese Community schon hat.',
  'Os marcos abaixo foram escolhidos para não haver como alcançá-los sozinho — todos precisam de mais de uma pessoa, ao longo do tempo.': 'Die Meilensteine unten sind so gewählt, dass man sie nicht allein erreichen kann — jeder braucht mehr als eine Person, über die Zeit.',
  'Progresso de {marco}': 'Fortschritt bei {marco}',
  'Quatro caracteres, um ícone e uma cor que aparecem ao lado do nome de quem é daqui.': 'Vier Zeichen, ein Symbol und eine Farbe, die neben dem Namen von allen von hier auftauchen.',
  'Só quem administra pode instalar ou tirar.': 'Nur Admins können sie installieren oder entfernen.',
  'Turma formada': 'Eine Truppe',
  'Um pacote instalado entra para toda a comunidade: os emojis dele passam a valer nas mensagens de todo mundo.': 'Ein installiertes Paket gehört der ganzen Community: seine Emojis gelten ab dann in den Nachrichten von allen.',
  'Vozes juntas': 'Stimmen zusammen',
  'Anil': 'Indigo',
  'Apaga a sua conta, as suas mensagens e o seu avatar. Os canais, emojis e sons que você criou continuam no servidor para os outros.': 'Löscht dein Konto, deine Nachrichten und deinen Avatar. Die Kanäle, Emojis und Sounds, die du erstellt hast, bleiben für die anderen auf dem Server.',
