  'Corta a voz em batidas, como as pás girando.': 'Zerhackt die Stimme in Schläge, wie drehende Rotorblätter.',
  'Desligado, a transmissão de quem está na sala aparece como convite e só começa a ser baixada quando você clica em Assistir. Isso poupa internet e processador — principalmente em sala cheia.': 'Aus erscheint der Stream von jemandem im Raum als Einladung und wird erst heruntergeladen, wenn du auf Ansehen klickst. Das spart Datenvolumen und Prozessor — vor allem im vollen Raum.',
