  'Sai uma letra e cada um escreve uma palavra com ela em cada categoria. Quem completar primeiro aperta STOP, e a turma decide o que vale.': 'Ein Buchstabe wird gezogen, und alle schreiben in jede Kategorie ein Wort damit. Wer zuerst alles hat, drückt STOPP, und die Truppe entscheidet, was zählt.',
  'Sudoku': 'Sudoku',
  'Todo mundo recebe o mesmo sudoku, e a sala vê quem está mais perto de terminar.': 'Alle bekommen dasselbe Sudoku, und der Raum sieht, wer am nächsten dran ist.',
  'Cinco em linha': 'Fünf in einer Reihe',
  'Duas pessoas põem pedras no tabuleiro, uma de cada vez. Vence quem fizer cinco seguidas. A sala assiste.': 'Zwei Leute setzen abwechselnd Steine aufs Brett. Wer fünf in einer Reihe hat, gewinnt. Der Raum schaut zu.',
  'Mancala': 'Mancala',
  'O jogo de semear: pegue as sementes de uma casa e espalhe uma por casa. Vence quem guardar mais no depósito. A sala assiste.': 'Das Säspiel: Nimm die Samen aus einer Mulde und verteil sie einzeln auf die nächsten. Wer am meisten im Speicher sammelt, gewinnt. Der Raum schaut zu.',
