  'Entre na sala de voz para jogar com a turma.': 'Geh in den Sprachraum, um mit der Truppe zu spielen.',
  'Já tem uma partida acontecendo nesta sala.': 'In diesem Raum läuft schon eine Partie.',
  'Só quem começou a partida pode encerrá-la antes do fim.': 'Nur wer die Partie gestartet hat, kann sie vorzeitig beenden.',
  'Lobisomem': 'Werwolf',
  'À noite, escolha com os outros lobisomens quem atacar. De dia, não deixe ninguém desconfiar.': 'Wähl nachts mit den anderen Werwölfen aus, wen ihr angreift. Tagsüber lass niemanden misstrauisch werden.',
  'Vidente': 'Orakel',
  'À noite, descubra se alguém é lobisomem. Conte de dia, se achar que vale o risco.': 'Find nachts heraus, ob jemand ein Werwolf ist. Erzähl es tagsüber, wenn es dir das Risiko wert ist.',
  'Anjo': 'Schutzengel',
  'À noite, escolha alguém para proteger. Se os lobisomens atacarem essa pessoa, ela sobrevive.': 'Wähl nachts jemanden, den du beschützt. Greifen die Werwölfe diese Person an, überlebt sie.',
  'Da vila': 'Vom Dorf',
  'À noite, durma. De dia, descubra quem são os lobisomens e vote para tirá-los do jogo.': 'Nachts schläfst du. Tagsüber findest du heraus, wer die Werwölfe sind, und stimmst sie aus dem Spiel.',
  'A vila venceu!': 'Das Dorf hat gewonnen!',
  'Os lobisomens venceram!': 'Die Werwölfe haben gewonnen!',
  'Noite {n}. A vila dorme.': 'Nacht {n}. Das Dorf schläft.',
  'Os lobisomens atacaram {nome} durante a noite.': 'Die Werwölfe haben in der Nacht {nome} angegriffen.',
  'Ninguém morreu esta noite.': 'In dieser Nacht ist niemand gestorben.',
  'Dia {n}. Conversem e votem em quem vocês acham que é lobisomem.': 'Tag {n}. Redet miteinander und stimmt ab, wen ihr für einen Werwolf haltet.',
  'A vila tirou {nome} do jogo.': 'Das Dorf hat {nome} aus dem Spiel gestimmt.',
  'Empate: ninguém sai hoje.': 'Gleichstand: Heute fliegt niemand raus.',
  'Clique em quem os lobisomens vão atacar.': 'Klick auf die Person, die die Werwölfe angreifen.',
  'Você já usou a sua visão esta noite.': 'Du hast deine Vision heute Nacht schon benutzt.',
  'Clique em alguém para descobrir se é lobisomem.': 'Klick auf jemanden, um herauszufinden, ob es ein Werwolf ist.',
  'Clique em quem você quer proteger esta noite.': 'Klick auf die Person, die du heute Nacht beschützen willst.',
  'Durma. Os outros papéis estão agindo.': 'Schlaf. Die anderen Rollen sind am Werk.',
  'Você saiu do jogo. Agora só assiste — sem contar nada!': 'Du bist raus. Jetzt schaust du nur noch zu — nichts verraten!',
  'Clique em quem você quer tirar do jogo. O mais votado sai; empate, ninguém.': 'Klick auf die Person, die du rauswählen willst. Wer die meisten Stimmen hat, fliegt raus; bei Gleichstand niemand.',
