  'Problemas de xadrez': 'Schachaufgaben',
  'Todo mundo recebe o mesmo problema do Lichess. Quem achar o lance certo mais rápido ganha o ponto extra.': 'Alle bekommen dieselbe Lichess-Aufgabe. Wer am schnellsten den richtigen Zug findet, bekommt den Extrapunkt.',
