  'Solo': 'Solo',
  'Coletivo': 'Gemeinsam',
  'Palavra secreta': 'Geheimwort',
  'Todo mundo tenta adivinhar a mesma palavra de 5 letras, em 6 chutes. A sala vê as cores dos outros, mas não as letras. Quem acertar com menos chutes ganha mais pontos.': 'Alle versuchen, dasselbe Wort mit 5 Buchstaben in 6 Versuchen zu erraten. Man sieht die Farben der anderen, aber nicht ihre Buchstaben. Wer es mit weniger Versuchen schafft, bekommt mehr Punkte.',
