  '{tipo} «{item}» ({onde}) saiu do Syden porque {quem} disse ter os direitos. Se você tinha autorização para publicar, responda aqui contando: a sua resposta vai ser levada em conta. Enquanto isso não ficar claro, fica fora. Os termos explicam como funciona, na seção 4: https://syden.chat/termos.html#direito-autoral': '{tipo} «{item}» ({onde}) wurde aus Syden entfernt, weil {quem} angibt, die Rechte daran zu haben. Wenn du die Erlaubnis zur Veröffentlichung hattest, antworte hier und erklär es: Deine Antwort wird berücksichtigt. Solange das nicht geklärt ist, bleibt der Inhalt entfernt. Die Bedingungen erklären in Abschnitt 4, wie das funktioniert: https://syden.chat/termos.html#direito-autoral',
