  'Copa da turma': 'Pokal der Gruppe',
  'Copas da Cenoura que a turma correu até o fim, na Corrida dos coelhos.': 'Karottenpokale, die die Gruppe im Hasenrennen bis zum Ende gefahren ist.',
  'Bosque': 'Wald',
  'Cânion': 'Canyon',
  'Copa do Repolho': 'Kohlpokal',
  'Festa dos coelhos': 'Hasenparty',
  'Cinco rodadas de jogos rápidos, cada um na própria tela: reflexo, pontaria, memória e olho. Quem for melhor em cada rodada ganha mais pontos.': 'Fünf Runden schnelle Spiele, alle am eigenen Bildschirm: Reaktion, Zielen, Gedächtnis und Augenmaß. Wer in einer Runde am besten ist, bekommt mehr Punkte.',
  'Saque rápido': 'Schnellziehen',
  'Espere o sinal e aperte o mais rápido que puder. Antes do sinal, está fora.': 'Warte auf das Signal und drück so schnell du kannst. Vor dem Signal bist du raus.',
  'Medidor de força': 'Kraftmesser',
  'Pare a barra o mais perto possível de 100%.': 'Halte den Balken so nah wie möglich bei 100 % an.',
  'Parar o relógio': 'Stopp die Uhr',
  'Pare o relógio em 10 segundos exatos. Os números somem depois de 3.': 'Stopp die Uhr bei genau 10 Sekunden. Die Zahlen verschwinden nach 3.',
  'Jogo dos copos': 'Hütchenspiel',
  'Veja onde fica a cenoura e siga o copo. Acertar mais rápido vale mais.': 'Schau, wo die Karotte ist, und folge dem Becher. Je schneller du richtig liegst, desto mehr zählt es.',
  'Siga o coelho': 'Folge dem Hasen',
  'Repita as setas na ordem. A cada acerto, vem mais uma.': 'Wiederhole die Pfeile in der Reihenfolge. Mit jedem Treffer kommt einer dazu.',
  'Tiro ao alvo': 'Zielschießen',
  'Acerte os alvos que aparecerem. Cada um vale um ponto.': 'Triff die Zielscheiben, die auftauchen. Jede zählt einen Punkt.',
  'Cedo demais!': 'Zu früh!',
  'Não valeu': 'Zählt nicht',
