  'Ouça, repita a batida no mesmo ritmo e acrescente uma no fim.': 'Hör zu, wiederhol den Schlag im gleichen Takt und häng einen dran.',
  'Paiol': 'Speicher',
  'Pare cada faixa com o retrato no lugar, de cima para baixo.': 'Stopp jeden Streifen mit dem Porträt an der richtigen Stelle, von oben nach unten.',
  'Pare os três rolos na mesma figura. Cada trinca vale um ponto.': 'Stopp die drei Walzen auf derselben Figur. Jeder Dreier zählt einen Punkt.',
  'Pedras': 'Steine',
  'Pegue a galinha': 'Fang das Huhn',
  'Pegue as cenouras no gelo e fuja dos repolhos.': 'Schnapp dir die Karotten auf dem Eis und weich den Kohlköpfen aus.',
  'Pegue uma cenoura dourada e leve até a porteira. Falta uma: empurre quem estiver carregando!': 'Schnapp dir eine goldene Karotte und bring sie zum Tor. Eine fehlt: Schubs, wer eine trägt!',
