  'Pula o ponteiro': 'Spring über den Zeiger',
  'Pule do balanço para cair numa folha. A mais longe vale mais.': 'Spring von der Schaukel auf ein Blatt. Das weiteste zählt mehr.',
  'Pule quando o ponteiro passar. Ele fica cada vez mais rápido.': 'Spring, wenn der Zeiger vorbeikommt. Er wird immer schneller.',
