  'Sem vidas: agora é torcer pela turma.': 'Keine Leben mehr: Jetzt heißt es, die Truppe anfeuern.',
  'Siga os bichos de toca em toca. No fim, aponte onde está o do balão.': 'Folge den Tieren von Bau zu Bau. Zeig am Ende, wo das mit dem Ballon ist.',
  'Silo': 'Silo',
  'Solte o cipó quando ele estiver na faixa clara.': 'Lass die Liane los, wenn sie im hellen Streifen ist.',
  'Solte quando o nabo apontar para o campo. Girando mais rápido, vai mais longe.': 'Lass los, wenn die Rübe aufs Feld zeigt. Je schneller sie sich dreht, desto weiter fliegt sie.',
  'Suba até o cata-vento. O que cai e os corvos levam de volta ao último andar.': 'Klettere bis zur Wetterfahne. Stürze und Krähen bringen dich zurück ins letzte Stockwerk.',
  'Suba o celeiro por tábuas, fardos e vigas que se mexem até o cata-vento lá no alto, desviando das ferramentas que caem e dos corvos. No Solo, contra o relógio e os fantasmas dos amigos.': 'Klettere über Bretter, Heuballen und bewegliche Balken die Scheune hinauf bis zur Wetterfahne ganz oben, und weich fallendem Werkzeug und Krähen aus. Im Solo gegen die Uhr und die Geister deiner Freunde.',
