  '{n} voltas': '{n} Runden',
  'A energia é a vida e o turbo: bater na borda gasta, a faixa cor-de-rosa recarrega.': 'Die Energie ist Leben und Turbo zugleich: Am Rand anzustoßen kostet sie, der rosa Streifen lädt sie auf.',
  'A nave explodiu: a energia acabou.': 'Das Schiff ist explodiert: Die Energie ist alle.',
  'Posição: {posicao} de {total}': 'Position: {posicao} von {total}',
  'Escolher a pista': 'Strecke wählen',
  'Corrida de naves-cenoura numa pista suspensa, muito mais rápida que o kart. A energia é a vida e o turbo: bater na borda gasta, a faixa cor-de-rosa recarrega, e sair da pista é cair. No Solo, contra o relógio e os fantasmas dos amigos.': 'Ein Rennen mit Karottenschiffen auf einer schwebenden Strecke, viel schneller als das Kart. Die Energie ist Leben und Turbo zugleich: Am Rand anzustoßen kostet sie, der rosa Streifen lädt sie auf, und wer von der Strecke abkommt, stürzt ab. Solo gegen die Uhr und die Geister deiner Freunde.',
  'Os karts numa arena fechada, cada um com três balões. Pegue as caixas e use os itens para estourar os balões dos outros: quem fica sem balão sai, e ganha quem sobrar.': 'Die Karts in einer geschlossenen Arena, jedes mit drei Ballons. Schnapp dir die Kisten und bring mit den Items die Ballons der anderen zum Platzen: Wer keinen Ballon mehr hat, scheidet aus, und wer übrig bleibt, gewinnt.',
  'Esquadrilha da toca': 'Staffel aus dem Bau',
  'Aviõezinhos de cenoura contra a praga da horta: desvie das sementes, pegue os reforços e derrube o espantalho mecânico no fim. A turma voa as mesmas ondas, e a esquadrilha soma os pontos.': 'Kleine Karottenflieger gegen die Gartenschädlinge: weich den Samen aus, schnapp dir die Verstärkung und hol am Ende die mechanische Vogelscheuche runter. Die Gruppe fliegt dieselben Wellen, und die Punkte der Staffel werden zusammengezählt.',
