  'Minigolfe 3D': 'Minigolf 3D',
  'Oito buracos em 3D, com rampas, castelo e moinho, todos jogando o mesmo ao mesmo tempo. Arraste para mirar e dar a força, e solte. Ganha quem somar menos tacadas.': 'Acht Löcher in 3D, mit Rampen, Burg und Windmühle, alle spielen gleichzeitig dasselbe. Zieh zum Zielen und für die Kraft, und lass los. Es gewinnt, wer insgesamt die wenigsten Schläge hat.',
  'Ver o buraco de cima': 'Loch von oben ansehen',
  'Fora da pista! Mais uma tacada.': 'Von der Bahn! Ein Schlag mehr.',
  'Arraste para o lado para mirar e para baixo para a força, e solte. No teclado: as setas miram, e o Espaço segurado dá a força.': 'Zieh zur Seite zum Zielen und nach unten für die Kraft, und lass los. Mit der Tastatur: Die Pfeiltasten zielen, und die gehaltene Leertaste gibt die Kraft.',
  'Futebol dos coelhos': 'Hasenfußball',
  'Futebol de campo pequeno, visto de cima. Encoste na bola para conduzir, segure Espaço para chutar mais forte e passe com X. Na sala, os times se completam com robôs.': 'Kleinfeldfußball, von oben gesehen. Berühr den Ball, um ihn zu führen, halte die Leertaste für einen stärkeren Schuss und passe mit X. Im Raum werden die Teams mit Bots aufgefüllt.',
