  'Caça às pragas da horta': 'Schädlingsjagd im Garten',
  'Corvos e gafanhotos atacam a horta. Mire e clique para acertar antes que fujam: a munição é contada, e cada onda vem mais rápida. Ganha quem fizer mais pontos.': 'Krähen und Heuschrecken greifen den Garten an. Ziel und klick, um sie zu treffen, bevor sie entkommen: Die Munition ist abgezählt, und jede Welle kommt schneller. Wer die meisten Punkte holt, gewinnt.',
  'Mire e clique nas pragas antes que fujam. Cada tiro gasta uma cenoura.': 'Ziel und klick auf die Schädlinge, bevor sie entkommen. Jeder Schuss kostet eine Karotte.',
