  '{nome} chegou à cenoura dourada.': '{nome} hat die goldene Karotte erreicht.',
  'Quantas rodadas?': 'Wie viele Runden?',
  'Os coelhos defendem a horta de raposas, corvos e um texugo. Andem juntos, batam em combo e cuidem uns dos outros: de 1 a 4 pessoas.': 'Die Hasen verteidigen den Garten gegen Füchse, Krähen und einen Dachs. Lauft zusammen, schlagt in Combos und passt aufeinander auf: 1 bis 4 Personen.',
  'Pulo do coelho': 'Hasensprung',
  'Uma corrida de plataforma: correr, pular e não cair. Sozinho, contra o relógio e os fantasmas dos amigos; com a turma, ao vivo, numa fase ou nas três.': 'Ein Plattform-Rennen: rennen, springen und nicht fallen. Allein gegen die Uhr und die Geister deiner Freunde; mit der Gruppe live, in einem Level oder in allen drei.',
  'Troque dois legumes vizinhos para juntar três ou mais iguais. A pilha sobe sem parar: não deixe chegar ao topo. Com a turma, as cadeias e os combos mandam caixotes para os outros.': 'Tausch zwei benachbarte Gemüse, um drei oder mehr gleiche zusammenzubringen. Der Stapel steigt ohne Pause: Lass ihn nicht die Spitze erreichen. Mit der Gruppe schicken Ketten und Combos den anderen Kisten.',
  'Seis buracos de minigolfe, todos jogando o mesmo ao mesmo tempo. Puxe a bola para trás e solte para dar a tacada. Ganha quem somar menos tacadas.': 'Sechs Minigolf-Löcher, alle spielen gleichzeitig dasselbe. Zieh den Ball nach hinten und lass los, um zu schlagen. Es gewinnt, wer insgesamt die wenigsten Schläge hat.',
  'Cada um joga o dado na sua vez e anda pela horta. Junte cenouras para comprar a cenoura dourada, e depois de cada rodada a turma joga um microjogo. Ganha quem tiver mais cenouras douradas.': 'Reihum wird gewürfelt und durch den Garten gezogen. Sammle Karotten, um die goldene Karotte zu kaufen, und nach jeder Runde spielt die Gruppe ein Minispiel. Es gewinnt, wer die meisten goldenen Karotten hat.',
