  'Ande pelas capitais do Brasil, compre cidades e cobre aluguel de quem parar nelas. Com uma região inteira, dá para construir prédios. Troque, dispute nos leilões e não fique sem dinheiro.': 'Zieh durch die Hauptstädte Brasiliens, kauf Städte und kassiere Miete von allen, die darauf landen. Mit einer ganzen Region kannst du Gebäude bauen. Tausche, biete bei Versteigerungen mit und geh nicht pleite.',
