  'Batalha naval': 'Schiffe versenken',
  'O dominó de sempre, de 2 a 4 pessoas (com 4, em duplas). Encaixe as pedras pelas pontas, e quem bater primeiro leva os pontos das mãos dos outros.': 'Das klassische Domino für 2 bis 4 Leute (zu viert in Zweierteams). Leg die Steine an die Enden an – wer zuerst alle los ist, bekommt die Punkte aus den Händen der anderen.',
  'O truco paulista, com vira e manilha, em 2 ou em duplas de 4. Peça truco, aumente para seis, nove e doze, ou corra. Ganha quem fizer 12 pontos.': 'Truco aus São Paulo, mit Wendekarte und Trümpfen, zu zweit oder zu viert in Teams. Ruf Truco, erhöh auf sechs, neun und zwölf oder steig aus. Wer 12 Punkte holt, gewinnt.',
  'As damas brasileiras: comer é obrigatório, para a frente e para trás, e a dama anda a diagonal inteira. A sala assiste.': 'Brasilianische Dame: Schlagen ist Pflicht, vorwärts und rückwärts, und die Dame zieht über die ganze Diagonale. Der Raum schaut zu.',
  'Cada um esconde a sua frota e atira no mar do outro. Acertou, atira de novo. Vence quem afundar a frota inteira primeiro. A sala assiste.': 'Jeder versteckt seine Flotte und schießt ins Meer des anderen. Getroffen? Dann schieß noch mal. Wer zuerst die ganze Flotte versenkt, gewinnt. Der Raum schaut zu.',
