  'Cozinha da toca': 'Die Küche im Bau',
  'Pegue os ingredientes nos caixotes, pique na tábua, cozinhe no fogão e no forno sem queimar, monte no prato e entregue na janela. Todos recebem os mesmos pedidos: ganha quem entregar mais pratos em 3 minutos.': 'Nimm die Zutaten aus den Kisten, schneide sie auf dem Brett, gare sie auf dem Herd und im Ofen, ohne dass sie verbrennen, richte sie auf dem Teller an und gib sie am Fenster ab. Alle bekommen dieselben Bestellungen: Wer in 3 Minuten die meisten Teller abgibt, gewinnt.',
