  // Saúde do servidor: ações da Hetzner e diagnóstico do host
  "Diagnóstico do host": "Host-Diagnose",
  "Registros limitados de Docker, SSH, logind e kernel dos três boots mais recentes. Podem conter endereços IP.": "Begrenzte Protokolle von Docker, SSH, logind und Kernel aus den drei letzten Starts. Können IP-Adressen enthalten.",
  "Atualizar diagnóstico": "Diagnose aktualisieren",
  "Ainda não há snapshot. Ele será coletado na próxima abertura do cofre.": "Noch kein Snapshot. Er wird beim nächsten Öffnen des Tresors erfasst.",
  "Coletado em {data}": "Erfasst am {data}",
  "Medido pela {nome}": "Gemessen von {nome}",
  "Os mesmos números do painel do provedor. Inclui o disco, que o servidor não mede sozinho.": "Dieselben Zahlen wie im Dashboard des Anbieters. Inklusive Festplatte, die der Server nicht selbst misst.",
  "Ações no servidor": "Aktionen am Server",
  "O histórico da Hetzner: ligar, desligar e reiniciar, pelo painel ou pela API. Uma queda sem ação aqui não foi comandada por esses caminhos.": "Der Verlauf bei Hetzner: Einschalten, Herunterfahren und Neustart, über das Dashboard oder die API. Ein Ausfall ohne Aktion hier wurde auf keinem dieser Wege ausgelöst.",
