  'Apagado': "Entfernen",
  'Desfoca, apaga ou troca o que aparece atrás de você. A imagem da câmera não sai do computador para isso.': "Zeichnet weich, entfernt oder ersetzt, was hinter dir zu sehen ist. Das Kamerabild verlässt dafür deinen Computer nicht.",
  // A transmissão personalizada (16/11/2026)
  'Nativa': "Nativ",
  'Resolução': "Auflösung",
  'Quadros por segundo': "Bilder pro Sekunde",
  'Para quando a escolha automática errar: a resolução e os quadros ficam os que você escolher, do começo ao fim da transmissão.': "Für den Fall, dass die automatische Wahl danebenliegt: Auflösung und Bilder bleiben so, wie du sie wählst, vom Anfang bis zum Ende der Übertragung.",
  // O Syden Broadcast (16/11/2026)
  'Os efeitos de voz e de câmera feitos no seu computador, sem enviar nada a um servidor.': "Die Effekte für Stimme und Kamera, die auf deinem Computer laufen, ohne etwas an einen Server zu schicken.",
  // O Comando Cenoura (16/11/2026)
  'Comando Cenoura': "Karotten-Kommando",
  'Correr e atirar com a turma: o lança-cenouras mira em oito direções, a granada abre caminho e quem solta os coelhinhos presos ganha reforço. O dragão espera no fim: de 1 a 4 pessoas.': "Lauf und schieß mit der Gruppe: Der Karottenwerfer zielt in acht Richtungen, die Granate macht den Weg frei, und wer die eingesperrten Häschen befreit, bekommt Verstärkung. Am Ende wartet der Drache: 1 bis 4 Leute.",
  'Andar e mirar': "Laufen und zielen",
  'Granada': "Granate",
  // A Masmorra da Toca (16/11/2026)
  'Masmorra da Toca': "Das Verlies im Bau",
  'Atravessem juntos a toca do rei-cogumelo: salas cheias de bichos, um baú com a cenoura que vai e volta, botões que pedem dois ao mesmo tempo e a porta trancada. De 1 a 4 pessoas.': "Durchquert gemeinsam den Bau des Pilzkönigs: Räume voller Viecher, eine Truhe mit der Karotte, die hin- und zurückfliegt, Schalter, die zwei gleichzeitig brauchen, und die verschlossene Tür. 1 bis 4 Leute.",
  // O Ringue da Toca (16/11/2026)
  'Ringue da Toca': "Bau-Ring",
  'Boxe de reflexo contra três adversários do computador. Leia o aviso de cada golpe, esquive ou defenda e bata na brecha. Bater quando a luva brilha enche a estrela do soco forte.': "Reflexboxen gegen drei Computergegner. Lies die Ankündigung jedes Schlags, weich aus oder block und schlag in die Lücke. Schlägst du, wenn der Handschuh blitzt, füllt sich der Stern des harten Schlags.",
  'Esquivar': "Ausweichen",
  'Abaixar e defender': "Ducken und blocken",
  'Socar': "Schlagen",
  'Soco forte': "Harter Schlag",
  'Aperte os socos para levantar!': "Drück die Schlagtasten, um aufzustehen!",
  'Lutas vencidas: {n}': "Gewonnene Kämpfe: {n}",
  'Nocaute!': "K.o.!",
  // A Rota Estelar (16/11/2026)
  'Rota Estelar': "Sternenroute",
  'Coelhos em naves pela superfície de um planeta e pelo espaço: atire, segure o tiro para travar a mira, gire para desviar dos tiros e escolha o caminho na bifurcação. A turma voa a mesma rota, e o chefe espera no fim.': "Hasen in Raumschiffen über die Oberfläche eines Planeten und hinaus ins All: Schieß, halte den Schuss gedrückt, um ein Ziel zu erfassen, dreh dich, um Schüsse abzuwehren, und wähl an der Gabelung einen Weg. Die Gruppe fliegt dieselbe Route, und am Ende wartet der Boss.",
  'Pirueta': "Drehung",
  'Segure para travar a mira': "Halten zum Erfassen",
  // O Pinball da Horta (16/11/2026)
  'Pinball da Horta': "Gemüsegarten-Pinball",
  'Uma mesa de pinball na horta: segure a mola, rebata nos repolhos e derrube as três cenouras para acender a toca do coelho, que solta mais uma bola. Três bolas, e sacudir demais trava a mesa.': "Ein Pinballtisch im Gemüsegarten: Halt die Feder, prall an den Kohlköpfen ab und wirf die drei Karotten um, damit der Hasenbau leuchtet und noch eine Kugel freigibt. Drei Kugeln, und zu viel Rütteln sperrt den Tisch.",
