  'Lendas da Toca': "Legenden des Baus",
  'Um RPG de turnos curto: cada um controla um herói da turma. Escolham juntos, combinem ataques e vençam o dragão do castelo.': "Ein kurzes rundenbasiertes RPG: Jede Person steuert eine Heldenfigur der Gruppe. Wählt gemeinsam, kombiniert Angriffe und besiegt den Drachen der Burg.",
