  'Bichos da Toca': "Bautierchen",
  'Ande pelo campo, faça amizade com os bichos do mato usando uma cenoura e monte uma equipe de até seis. Vença o desafio da casa azul e, na sala, lute com a equipe de um amigo.': "Streif durch die Felder, freunde dich mit einer Karotte mit den Tierchen im hohen Gras an und stell ein Team aus bis zu sechs zusammen. Besteh die Herausforderung im blauen Haus und kämpf im Raum gegen das Team eines Freundes.",
