  "Levadiça": "Zugbrücke",
  'Nenhuma conversa ainda. Toque em alguém na lista de pessoas da comunidade e escolha "Enviar mensagem".': "Noch keine Unterhaltungen. Tippe in der Mitgliederliste der Community auf jemanden und wähl „Nachricht senden“.",
