  "Vocês derrubaram os dois centros da vila da outra equipe.": "Ihr habt beide Dorfzentren des anderen Teams zerstört.",
  // Os mini-games e as insígnias (19/11/2026)
  "A cidade que ninguém compra vai a leilão. Hipotecar uma cidade dá dinheiro, mas ela não cobra aluguel.": "Eine Stadt, die niemand kauft, wird versteigert. Eine Hypothek auf eine Stadt bringt Geld, aber dann kassiert sie keine Miete.",
  "A dica acende a peça que move. O problema com dica não pontua; na corrida, ela tira 10 segundos.": "Der Tipp lässt die Figur aufleuchten, die zieht. Eine Aufgabe mit Tipp bringt keine Punkte; im Rennen kostet er 10 Sekunden.",
  "A manilha é o valor seguinte ao da vira e ganha de todas. Entre elas: ouros, espadas, copas e paus, o zap.": "Der Trumpf ist der Wert nach dem der Wendekarte und schlägt alle. Untereinander: Karo, Pik, Herz und Kreuz, der Zap.",
  "A última nave de cada volta sai.": "Das letzte Schiff jeder Runde scheidet aus.",
  "Abaixar": "Ducken",
  "Acertos em sequência: {n}": "Richtig in Folge: {n}",
  "Ande pelo dado e compre a capital onde parar. Quem para na cidade de outro paga aluguel.": "Zieh mit dem Würfel und kauf die Hauptstadt, auf der du landest. Wer auf der Stadt eines anderen landet, zahlt Miete.",
  "Cada linha, coluna e bloco de 3 × 3 tem os números de 1 a 9, sem repetir.": "Jede Zeile, Spalte und jeder 3 × 3-Block enthält die Zahlen von 1 bis 9 ohne Wiederholung.",
  "Cada um recebe 3 cartas. Leva a mão quem ganhar 2 das 3 rodadas.": "Alle bekommen 3 Karten. Die Hand holt, wer 2 der 3 Runden gewinnt.",
  "Campeonato": "Meisterschaft",
  "Com 11 pontos, a dupla vê as cartas e decide se joga a mão de onze. Vence quem chegar a 12.": "Mit 11 Punkten sieht das Team die Karten und entscheidet, ob es die Elferhand spielt. Wer 12 erreicht, gewinnt.",
  "Com a região inteira, construa até 4 prédios: o aluguel sobe a cada um.": "Mit der ganzen Region baust du bis zu 4 Gebäude: Die Miete steigt mit jedem.",
  "Com estrelas, o soco forte (★) gasta todas de uma vez e dói mais.": "Mit Sternen verbraucht der harte Schlag (★) alle auf einmal und tut mehr weh.",
  "Dica": "Tipp",
  "Dica: este problema não pontua": "Tipp: Diese Aufgabe bringt keine Punkte",
  "Dica: tira 10 segundos": "Tipp: kostet 10 Sekunden",
  "Eliminação": "Ausscheidung",
  "Encoste uma pedra numa ponta da mesa com o mesmo número.": "Leg einen Stein mit der gleichen Zahl an ein Ende auf dem Tisch.",
  "Escolha a casa e depois o número. O lápis anota só para você.": "Wähl das Feld und dann die Zahl. Der Bleistift notiert nur für dich.",
  "Esquive do golpe e soque logo depois: é o contra-ataque, e vale estrela.": "Weich dem Schlag aus und schlag gleich danach: Das ist der Konter, und er bringt einen Stern.",
  "Fora da corrida na volta {n}.": "In Runde {n} ausgeschieden.",
  "Força das cartas": "Stärke der Karten",
  "Ganha o maior patrimônio no fim das rodadas, ou quem sobrar.": "Am Ende der Runden gewinnt das größte Vermögen, oder wer übrig bleibt.",
  "Iniciante": "Anfänger",
  "Mestre": "Meister",
  "Na sequência, cada acerto traz um problema mais difícil, e o primeiro erro acaba.": "In der Serie bringt jeder Treffer eine schwerere Aufgabe, und der erste Fehler beendet sie.",
  "O número pequeno no botão diz quantos ainda faltam.": "Die kleine Zahl auf der Taste zeigt, wie viele noch fehlen.",
  "Os cinco traçados seguidos contra o computador, com pontos.": "Die fünf Strecken nacheinander gegen den Computer, mit Punkten.",
  "Peça truco e a mão vale 3. Quem responde aceita, corre ou aumenta para 6, 9 ou 12.": "Ruf Truco, und die Hand zählt 3. Wer antwortet, nimmt an, steigt aus oder erhöht auf 6, 9 oder 12.",
  "Quem bate fica sem pedras e leva os pontos das mãos dos outros. Trancado, leva quem tem menos pontos na mão.": "Wer ausgeht, hat keine Steine mehr und bekommt die Punkte aus den Händen der anderen. Bei einer Blockade bekommt sie, wer die wenigsten Punkte auf der Hand hat.",
  "Sem pedra que sirva, compre. Sem nada para comprar, a vez passa.": "Passt kein Stein, zieh einen. Gibt es nichts mehr zu ziehen, ist der Nächste dran.",
  "Sequência": "Serie",
  "Soque quando a luva brilhar: o golpe para e você ganha uma estrela.": "Schlag, wenn der Handschuh blitzt: Der Schlag stoppt, und du bekommst einen Stern.",
