  "Saara": "Sahara",
  "Sai um animal secreto, e cada um chuta outros. Cada chute mostra o que bate com o secreto: a classe, a dieta, onde ele vive e o peso. Quem acertar com menos chutes ganha mais pontos.": "Ein geheimes Tier wird gezogen, und alle raten andere. Jeder Tipp zeigt, was mit dem geheimen übereinstimmt: die Klasse, die Ernährung, der Lebensraum und das Gewicht. Wer mit weniger Tipps trifft, bekommt mehr Punkte.",
  "Sai um dinossauro secreto, e cada um chuta outros. Cada chute mostra o que bate com o secreto: o período, a dieta, o grupo, o comprimento e onde ele foi achado. Quem acertar com menos chutes ganha mais pontos.": "Ein geheimer Dinosaurier wird gezogen, und alle raten andere. Jeder Tipp zeigt, was mit dem geheimen übereinstimmt: das Zeitalter, die Ernährung, die Gruppe, die Länge und der Fundort. Wer mit weniger Tipps trifft, bekommt mehr Punkte.",
  "Sai um elemento químico secreto, e cada um chuta outros. Cada chute mostra o que bate com o secreto: a família, o estado físico, o período, o grupo e o número atômico. Quem acertar com menos chutes ganha mais pontos.": "Ein geheimes chemisches Element wird gezogen, und alle raten andere. Jeder Tipp zeigt, was mit dem geheimen übereinstimmt: die Familie, der Aggregatzustand, die Periode, die Gruppe und die Ordnungszahl. Wer mit weniger Tipps trifft, bekommt mehr Punkte.",
  "Sai um estado secreto do Brasil, e cada um chuta outros. Cada chute mostra a distância e a direção até o secreto, a região, a população, a área, o litoral e a fronteira com outro país. Quem acertar com menos chutes ganha mais pontos.": "Ein geheimer Bundesstaat Brasiliens wird gezogen, und alle raten andere. Jeder Tipp zeigt die Entfernung und die Richtung zum geheimen, die Region, die Einwohnerzahl, die Fläche, die Küste und die Grenze zu einem anderen Land. Wer mit weniger Tipps trifft, bekommt mehr Punkte.",
  "Saturno": "Saturn",
